def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Each 2x2 block is framed by four diagonal markers. Each marker's ray
    # extends away from the block, recolored with its diagonally opposite marker.
    for r in range(h-3):
      for c in range(w-3):
        if all(grid[y][x]==2 for y in (r,r+1) for x in (c,c+1)):
          coords=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
          if any(y<0 or y>=h or x<0 or x>=w for y,x in coords): continue
          nw,ne,sw,se=[grid[y][x] for y,x in coords]
          for (y,x),color,dy,dx in [(coords[0],sw,-1,-1),(coords[1],nw,-1,1),(coords[2],se,1,-1),(coords[3],ne,1,1)]:
            while 0<=y<h and 0<=x<w:
              out[y][x]=color; y+=dy; x+=dx
    return out
